{"function": "() => {
    const bodyText = document.body.innerText;
    const lines = bodyText.split('\n');
    const keywords = ['deposited', 'repository', 'collection', 'housed at', 'housed in', 'stored', 'kept', 'ZISP', 'Zoological Institute', 'St. Petersburg', 'Leningrad', 'Hanoi', 'Tam Dao', 'Tamdao', 'Son La', 'Vinh Phuc', 'Thai Nguyen', 'Gia Lai', 'Tram Lap', 'Kannak', 'Naniu', 'Chiengkhouan', 'Ban Chiéng Khoang', 'Mé Linh', 'A Ruang', 'Ulyanovsk', 'Russia', 'type series', 'holotype', 'paratype', 'type specimens', 'specimen', 'label', 'drawer', 'cabinet', 'main collection', 'working material'];
    const relevant = [];
    for (let line of lines) {
        const lower = line.toLowerCase();
        if (keywords.some(kw => lower.includes(kw.toLowerCase()))) {
            relevant.push(line.trim());
        }
    }
    // Also search for phrases like "deposited in" more precisely
    const depositedRegex = /deposited in [^\.]+\.?/gi;
    const matches = bodyText.match(depositedRegex);
    if (matches) {
        matches.forEach(m => relevant.push(m.trim()));
    }
    // Remove duplicates
    const unique = [...new Set(relevant)];
    return unique.slice(0, 100); // limit to first 100 lines
}"}

