{"function": "() => {
    const bodyText = document.body.innerText;
    const lines = bodyText.split('\n');
    const depositionPhrases = ['deposited in', 'collection of ZISP', 'in the collection', 'kept in', 'stored in', 'housed at', 'housed in', 'repository', 'type specimens', 'holotype', 'paratype', 'type series', 'specimen', 'label', 'drawer', 'cabinet', 'main collection', 'Zoological Institute', 'ZISP', 'St. Petersburg', 'Leningrad'];
    const results = [];
    for (let line of lines) {
        const lower = line.toLowerCase();
        if (depositionPhrases.some(phrase => lower.includes(phrase.toLowerCase()))) {
            // Get previous line and next line for context
            const index = lines.indexOf(line);
            const prev = index > 0 ? lines[index - 1] : '';
            const next = index < lines.length - 1 ? lines[index + 1] : '';
            results.push({
                line: line.trim(),
                prev: prev.trim(),
                next: next.trim()
            });
        }
    }
    // Deduplicate by line content
    const seen = new Set();
    const unique = [];
    for (const r of results) {
        if (!seen.has(r.line)) {
            seen.add(r.line);
            unique.push(r);
        }
    }
    return unique.slice(0, 50);
}"}

