    // Method 2: Get text via textContent
    const textContent = await mainElement.textContent();

    // Method 3: Get all text via XPath //text()
    const allTextNodes = await page.evaluate(() => {
        const nodes = document.evaluate('//text()', document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
        let text = '';
        for (let i = 0; i < nodes.snapshotLength; i++) {
            text += nodes.snapshotItem(i).nodeValue + ' ';
        }
        return text;
    });

    // Method 4: Get text via CSS selector 'body' innerText
    const bodyText = await page.evaluate(() => document.body.innerText);

    // Method 5: Get text via document.documentElement.outerText
    const outerText = await page.evaluate(() => document.documentElement.outerText);

    // Method 6: Get text via selection simulation (select all)
    const selectionText = await page.evaluate(() => {
        const sel = window.getSelection();
        sel.selectAllChildren(document.body);
        const selected = sel.toString();
        sel.removeAllRanges();
        return selected;
    });

    // Method 7: Get text via innerHTML parsing (strip tags)
    const innerHTML = await mainElement.innerHTML();
    const strippedHTML = innerHTML.replace(/<[^>]*>/g, ' ');

    // Method 8: Get text via getTextContent of all child nodes
    const childText = await page.evaluate(() => {
        function getText(node) {
            if (node.nodeType === Node.TEXT_NODE) return node.nodeValue;
            if (node.nodeType === Node.ELEMENT_NODE) {
                let text = '';
                for (let child of node.childNodes) {
                    text += getText(child);
                }
                return text;
            }
            return '';
        }
        return getText(document.body);
    });

    // Method 9: Get text via regex extraction of deposition statements (just a sample)
    const depositionRegex = /deposited in the collection of ZISP|collection of ZISP|Zoological Institute/g;
    const depositionMatches = bodyText.match(depositionRegex) || [];

    // Return results
    return {
        innerText: innerText.substring(0, 500) + '...',
        textContent: textContent.substring(0, 500) + '...',
        allTextNodes: allTextNodes.substring(0, 500) + '...',
        bodyText: bodyText.substring(0, 500) + '...',
        outerText: outerText.substring(0, 500) + '...',
        selectionText: selectionText.substring(0, 500) + '...',
        strippedHTML: strippedHTML.substring(0, 500) + '...',
        childText: childText.substring(0, 500) + '...',
        depositionMatches: depositionMatches
    };
}"}

